"""
Abstract interface definition for AI-driven RCA generation and operational intelligence.
Ensures strict decoupling of AI providers from pipeline core orchestration logic.
"""

from __future__ import annotations
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional
from pipeline.models import OperationalMetadata


@dataclass
class RCAInsights:
    """Standardized operational intelligence insights generated by AI/Heuristic analyzers."""
    incident_reference: str
    severity: str
    status: str
    executive_summary: str
    technical_root_cause: str
    five_whys: List[str]
    capa_actions: List[Dict[str, str]]
    provider_name: str
    model_version: Optional[str] = None
    telemetry_summary: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "incident_reference": self.incident_reference,
            "severity": self.severity,
            "status": self.status,
            "executive_summary": self.executive_summary,
            "technical_root_cause": self.technical_root_cause,
            "five_whys": self.five_whys,
            "capa_actions": self.capa_actions,
            "provider_name": self.provider_name,
            "model_version": self.model_version,
            "telemetry_summary": self.telemetry_summary,
        }


class AbstractRCAEnhancer(ABC):
    """Abstract interface defining the contract for incident intelligence and RCA generation."""

    @abstractmethod
    def analyze_incident(self, metadata: OperationalMetadata) -> RCAInsights:
        """Analyzes pipeline operational telemetry and generates an SRE-grade RCA insight bundle."""
        pass
